# French typography: non-breaking space before ? ! : ; and inside « »
import re as _re
T = [(en, fr if 'textContent' in fr else _re.sub(r' ([?!:;»])', ' \\1', fr).replace('« ', '« ')) for en, fr in T]

bad = []
for en, fr in T:
    n = s.count(en)
    if n == 0: bad.append(en[:70]); continue
    s = s.replace(en, fr)
if bad:
    print('NOT FOUND:\n  ' + '\n  '.join(bad)); sys.exit(1)

# paths one level up
s = re.sub(r'(src|href)="(img|fonts|demo)/', r'\1="../\2/', s)
s = s.replace('url(fonts/', 'url(../fonts/')
s = re.sub(r'data-v="((?:tasmota|shelly)-[^"]+\.mp4)"', r'data-v="../\1"', s)
s = re.sub(r'href="((?:tasmota|shelly)-[^"]+\.mp4)"', r'href="../\1"', s)
